@js:var html=result;var out='';
if(html.indexOf('code: 478')>=0){
  out='【触发限流】请求过快被临时限制，请等待约10分钟后重试。';
}else{
  var doc=org.jsoup.Jsoup.parse(html);
  var ps=doc.select('.reader-body p');
  var keep=[];
  var ads=['永久域名','最新热门','热门板块','最佳浏览','Chrome','Safari','VPN','电报','t.me','18禁','付费章节','以下正文内容已隐藏','立即登录','开通VIP','解锁全站'];
  for(var i=0;i<ps.size();i++){
    var t=ps.get(i).text().trim();
    if(!t)continue;
    var isAd=false;
    for(var j=0;j<ads.length;j++){if(t.indexOf(ads[j])>=0){isAd=true;break;}}
    if(!isAd)keep.push(t);
  }
  if(keep.length==0){
    out='正文为空，可能页面变化或网络问题，请刷新重试。';
  }else{
    if(html.indexOf('以下正文内容已隐藏')>=0){keep.unshift('【会员章节，游客仅显示预览】');}
    out=keep.join('\n');
  }
}
